import json
# Search for documents containing both 'global' and 'ATOI' or 'global products' and 'atoi'
with open('data/corpus.jsonl') as f:
    for line in f:
        doc = json.loads(line)
        text = ' '.join(doc['paragraphs'])
        for td in doc['table_descriptions'].values():
            text += ' ' + td
        if 'global rolled products' in text.lower() or ('global' in text.lower() and 'atoi' in text.lower()):
            print(f\"doc_key={doc['doc_key']}\")
